class Solution {
public:
    string evaluate(string s, vector<vector<string>>& knowledge) {
        unordered_map<string, string> mp;
        mp.reserve(knowledge.size());
        for (auto& kv : knowledge) {
            mp[kv[0]] = kv[1];
        }
        string result;
        result.reserve(s.size());
        int i = 0, n = (int)s.size();
        while (i < n) {
            if (s[i] == '(') {
                ++i;
                string key;
                while (i < n && s[i] != ')') {
                    key.push_back(s[i]);
                    ++i;
                }
                ++i; // skip ')'
                auto it = mp.find(key);
                if (it != mp.end()) {
                    result += it->second;
                } else {
                    result.push_back('?');
                }
            } else {
                result.push_back(s[i]);
                ++i;
            }
        }
        return result;
    }
};
